    for x in range(W):
        for y in range(H):
            c = grid[y][x]
            if c != 0 and c != 2:
                max_y = max(max_y, y)

    t1 = max_y / 3
    t2 = 2 * max_y / 3

    if len(gray_rows) > 0:
        gray_row_val = min(gray_rows)
        if gray_row_val >= H // 2:
            target_rows = [0, 1, 2]
        else:
            target_rows = [H-3, H-2, H-1]
    else:
        target_rows = [0, 1, 2]

    output = [[0]*W for _ in range(H)]

